#!/usr/bin/env bash
#
# Generates src/gen/md_fonts.c, the Markdown's fonts (ui/markdown.c) beyond the others:
# Inter Bold at 24, 26 and 32 px (strong text, headings), Inter Medium Italic at 24 px
# (emphasis); Medium Italic and Bold Italic at 26 px for the rich text editor (rich_edit.c),
# from the dev shell's $INTER, with the characters of ui_font_<size> from
# Inter and its line height and baseline, falling back to ui_font_<size> (symbols,
# emoji). Code is in ui_font_mono_20.
#
# Run in `nix develop` (lv_font_conv): external/package/phone-ui/gen-md-fonts.sh
#

set -euo pipefail

here="$(cd "$(dirname "$0")" && pwd)"
ui="$here/src"

# In a scratch directory, with relative paths: the options are recorded in the output
tmp="$(mktemp -d)"
trap 'rm -rf "$tmp"' EXIT
cp "$INTER/Inter-Bold.ttf" "$INTER/Inter-Medium-Italic.ttf" "$INTER/Inter-Bold-Italic.ttf" "$tmp/"

# name, font file, size, ranges...
font() {
	local name=$1 file=$2 size=$3
	shift 3
	local ranges=()
	for r in "$@"; do ranges+=(-r "$r"); done
	(cd "$tmp" && lv_font_conv --no-compress --no-prefilter --bpp 4 --size "$size" --format lvgl \
		--font "$file" "${ranges[@]}" --lv-include lvgl.h --lv-font-name "$name" -o "$name.c")
	local base="$ui/gen/ui_font_$size.c"
	local line_height base_line
	line_height=$(sed -n 's/^ *\.line_height = \([0-9]*\),.*/\1/p' "$base")
	base_line=$(sed -n 's/^ *\.base_line = \([0-9]*\),.*/\1/p' "$base")
	sed -i -e "s/^\( *\.line_height = \)[0-9]*,/\1$line_height,/" \
	       -e "s/^\( *\.base_line = \)[0-9]*,/\1$base_line,/" \
	       -e "s/^\( *\.fallback = \)NULL,/\1\&ui_font_$size,/" \
	       -e "s|^/\*Initialize a public general font descriptor\*/|extern const lv_font_t ui_font_$size; /* phone-ui's */\n\n&|" \
	       "$tmp/$name.c"
	grep -q "fallback = &ui_font_$size" "$tmp/$name.c" || { echo "$name.c: no fallback" >&2; exit 1; }
}

# ui_font_<size>'s characters from Inter (gen-fonts.sh)
inter=(0x20-0x7E,0xA0-0x17F,0x218-0x21B,0x2010,0x2012-0x2015,0x2018-0x201A,0x201C-0x201E
	0x2020-0x2022,0x2026,0x2030,0x2032-0x2033,0x2039-0x203A 0x20AC,0x2122,0x221A,0x3C0,0x2206)
font md_bold_24 Inter-Bold.ttf 24 "${inter[@]}"
font md_bold_26 Inter-Bold.ttf 26 "${inter[@]}"
font md_bold_32 Inter-Bold.ttf 32 "${inter[@]}"
font md_italic_24 Inter-Medium-Italic.ttf 24 "${inter[@]}"
font md_italic_26 Inter-Medium-Italic.ttf 26 "${inter[@]}"
font md_bold_italic_26 Inter-Bold-Italic.ttf 26 "${inter[@]}"

{
	echo "/* Generated by gen-md-fonts.sh: the Markdown's fonts (ui/markdown.c) */"
	echo
	echo "#include \"lvgl.h\""
	echo
	for f in md_bold_24 md_bold_26 md_bold_32 md_italic_24 md_italic_26 md_bold_italic_26; do
		# One file: their tables' static names apart (not the struct members, after a dot)
		sed -e "s/\([^.]\)\bglyph_bitmap\b/\1${f}_glyph_bitmap/g" -e "s/\([^.]\)\bglyph_dsc\b/\1${f}_glyph_dsc/g" \
		    -e "s/\([^.]\)\bunicode_list_\([0-9]*\)\b/\1${f}_unicode_list_\2/g" -e "s/\([^.]\)\bcmaps\b/\1${f}_cmaps/g" \
		    -e "s/\([^.]\)\bkern_\(left_class_mapping\|right_class_mapping\|class_values\|pair_glyph_ids\|pair_values\|classes\|pairs\)\b/\1${f}_kern_\2/g" \
		    -e "s/\([^.]\)\bfont_dsc\b/\1${f}_font_dsc/g" -e "s/\([^.]\)\bcache\b/\1${f}_cache/g" \
		    -e '/^#ifdef LV_LVGL_H_INCLUDE_SIMPLE/,/^#endif/d' "$tmp/$f.c"
	done
} > "$tmp/md_fonts.c"
mv "$tmp/md_fonts.c" "$ui/gen/md_fonts.c"
